#include "command_supervisor.h"
static const char *reject_name(command_reject_t reason){switch(reason){case NACK_NONE:return "NONE";case NACK_DUPLICATE_SEQUENCE:return "DUPLICATE_SEQUENCE";case NACK_OLD_SEQUENCE:return "OLD_SEQUENCE";case NACK_OUT_OF_ORDER_SEQUENCE:return "OUT_OF_ORDER_SEQUENCE";case NACK_EXPIRED_COMMAND:return "EXPIRED_COMMAND";case NACK_HEARTBEAT_TIMEOUT:return "HEARTBEAT_TIMEOUT";case NACK_CONFIGURATION_MISMATCH:return "CONFIGURATION_MISMATCH";case NACK_NOT_ENABLED:return "NOT_ENABLED";default:return "INTERNAL_FAULT";}}
void command_supervisor_init(command_supervisor_t*s){s->seen=false;s->last_sequence=0;s->heartbeat_ns=0;s->phase1_output_disabled=true;s->last_rejection="NONE";}
command_reject_t command_supervisor_accept(command_supervisor_t*s,uint32_t q,uint64_t now,uint64_t until,bool match){command_reject_t result=NACK_NONE;if(!match)result=NACK_CONFIGURATION_MISMATCH;else if(until<=now)result=NACK_EXPIRED_COMMAND;else if(s->seen&&q==s->last_sequence)result=NACK_DUPLICATE_SEQUENCE;else if(s->seen&&(int32_t)(q-s->last_sequence)<0)result=NACK_OLD_SEQUENCE;if(result!=NACK_NONE){s->last_rejection=reject_name(result);return result;}s->seen=true;s->last_sequence=q;s->heartbeat_ns=now;s->last_rejection="NONE";return NACK_NONE;}
bool command_supervisor_heartbeat_expired(const command_supervisor_t*s,uint64_t now,uint64_t timeout){return !s->seen||now<s->heartbeat_ns||now-s->heartbeat_ns>timeout;}
void command_supervisor_force_safe_stop(command_supervisor_t*s,command_reject_t reason){s->phase1_output_disabled=true;s->last_rejection=reject_name(reason);}
